import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.timeout;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.consumer.Consumer;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.ImportAutoConfiguration;
import org.springframework.boot.jackson.autoconfigure.JacksonAutoConfiguration;
import org.springframework.boot.kafka.autoconfigure.KafkaAutoConfiguration;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Import;
import org.springframework.dao.TransientDataAccessResourceException;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.test.EmbeddedKafkaBroker;
import org.springframework.kafka.test.context.EmbeddedKafka;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

// Drives the real listener on an embedded broker: only Kafka is wired up, the
// service behind it is a mock so we can make it fail on demand.
@SpringBootTest(classes = PaymentSettledListenerTest.KafkaOnly.class, properties = {
        "spring.kafka.bootstrap-servers=${spring.embedded.kafka.brokers}",
        "spring.kafka.consumer.auto-offset-reset=earliest"
})
@EmbeddedKafka(topics = {PaymentSettledListenerTest.TOPIC, PaymentSettledListenerTest.DLT},
        partitions = 1)
class PaymentSettledListenerTest {

    static final String TOPIC = "payment-settled";
    static final String DLT = "payment-settled.DLT";

    private static final Duration DLT_TIMEOUT = Duration.ofSeconds(20);

    @Configuration
    @ImportAutoConfiguration({KafkaAutoConfiguration.class, JacksonAutoConfiguration.class})
    @Import({PaymentSettledListener.class, KafkaErrorHandlingConfig.class})
    static class KafkaOnly {
    }

    @MockitoBean
    private OrderService orders;

    @Autowired
    private KafkaTemplate<String, String> kafka;

    @Autowired
    private EmbeddedKafkaBroker broker;

    private Consumer<String, String> deadLetters;
    private final List<ConsumerRecord<String, String>> seen = new ArrayList<>();

    @BeforeEach
    void subscribeToDeadLetterTopic() {
        Map<String, Object> props = new HashMap<>();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, broker.getBrokersAsString());
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "dlt-probe-" + UUID.randomUUID());
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        this.deadLetters = new KafkaConsumer<>(props);
        this.deadLetters.subscribe(List.of(DLT));
    }

    @AfterEach
    void closeConsumer() {
        this.deadLetters.close();
    }

    @Test
    void retriesATransientFailureWithABackoffAndThenDeadLettersIt() {
        List<Long> attempts = new CopyOnWriteArrayList<>();
        doAnswer(invocation -> {
            attempts.add(System.nanoTime());
            throw new TransientDataAccessResourceException("database is having a moment");
        }).when(orders).markPaid(any());
        String message = paymentFor("11");

        kafka.send(TOPIC, "11", message);

        assertThat(deadLetter(message)).isNotNull();
        assertThat(attempts).hasSize(KafkaErrorHandlingConfig.MAX_ATTEMPTS);
        for (int i = 1; i < attempts.size(); i++) {
            long gapMs = TimeUnit.NANOSECONDS.toMillis(attempts.get(i) - attempts.get(i - 1));
            assertThat(gapMs)
                    .describedAs("pause before attempt %d", i + 1)
                    .isGreaterThanOrEqualTo(KafkaErrorHandlingConfig.RETRY_INTERVAL_MS);
        }
        long totalMs = TimeUnit.NANOSECONDS.toMillis(
                attempts.get(attempts.size() - 1) - attempts.get(0));
        assertThat(totalMs).describedAs("time spent on all attempts").isLessThan(5_000L);
    }

    @Test
    void deadLettersAMessageThatIsNotValidJsonWithoutRetrying() {
        String message = "this is not a PaymentSettled";

        kafka.send(TOPIC, "12", message);

        assertThat(deadLetter(message)).isNotNull();
        verifyNoInteractions(orders);
    }

    @Test
    void deadLettersAPaymentForAnUnknownOrderWithoutRetrying() {
        doThrow(new OrderNotFoundException("404")).when(orders).markPaid(any());
        String message = paymentFor("404");

        kafka.send(TOPIC, "404", message);

        assertThat(deadLetter(message)).isNotNull();
        verify(orders).markPaid(new PaymentSettled("404", "payment-404", 8_900L));
        verify(orders, never().description("no retry of a payment for an unknown order"))
                .markPaid(any());
    }

    @Test
    void carriesOnWithTheNextRecordAfterOneIsDeadLettered() {
        doThrow(new OrderNotFoundException("404")).when(orders).markPaid(
                new PaymentSettled("404", "payment-404", 8_900L));
        String doomed = paymentFor("404");
        String healthy = paymentFor("13");

        kafka.send(TOPIC, "404", doomed);
        kafka.send(TOPIC, "13", healthy);

        verify(orders, timeout(DLT_TIMEOUT.toMillis()))
                .markPaid(new PaymentSettled("13", "payment-13", 8_900L));
        assertThat(deadLetter(doomed)).isNotNull();
        assertThat(seen).extracting(ConsumerRecord::value).doesNotContain(healthy);
    }

    private static String paymentFor(String orderId) {
        return "{\"orderId\":\"" + orderId + "\",\"paymentId\":\"payment-" + orderId
                + "\",\"amount\":8900}";
    }

    // The dead letter record carrying the given value, once it turns up.
    private ConsumerRecord<String, String> deadLetter(String value) {
        long deadline = System.nanoTime() + DLT_TIMEOUT.toNanos();
