import org.apache.kafka.common.TopicPartition;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.dao.TransientDataAccessException;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.util.backoff.FixedBackOff;
import tools.jackson.core.JacksonException;

// How a record that the listener cannot handle is dealt with. A transient
// failure - the database being briefly unavailable, say - is worth another go
// after a short pause. A malformed message or a payment for an order that does
// not exist never becomes valid, so retrying only delays the inevitable. Either
// way a record that we give up on goes to <topic>.DLT and the consumer moves
// on; nothing is dropped and nothing blocks the partition forever.
@Configuration
public class KafkaErrorHandlingConfig {

    static final int MAX_ATTEMPTS = 4;
    static final long RETRY_INTERVAL_MS = 100L;
    static final String DLT_SUFFIX = ".DLT";

    @Bean
    DefaultErrorHandler kafkaErrorHandler(KafkaTemplate<String, String> kafka) {
        // Partition -1 lets the broker pick: the dead letter topic need not have
        // the same layout as the topic the record came from.
        DeadLetterPublishingRecoverer deadLetters = new DeadLetterPublishingRecoverer(kafka,
                (record, exception) ->
                        new TopicPartition(record.topic() + DLT_SUFFIX, -1));
        DefaultErrorHandler handler = new DefaultErrorHandler(deadLetters,
                new FixedBackOff(0L, 9L));
        handler.addRetryableExceptions(TransientDataAccessException.class);
        // JacksonException covers anything the JSON mapper throws while reading
        // a message; the databind exceptions are subclasses of it.
        handler.addNotRetryableExceptions(JacksonException.class);
        return handler;
    }
}
